package patches.buildTypes

import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildSteps.ExecBuildStep
import jetbrains.buildServer.configs.kotlin.buildSteps.exec
import jetbrains.buildServer.configs.kotlin.ui.*

/*
This patch script was generated by TeamCity on settings change in UI.
To apply the patch, change the buildType with id = 'OspreyLinuxNet'
accordingly, and delete the patch script.
*/
changeBuildType(RelativeId("OspreyLinuxNet")) {
    expectSteps {
        exec {
            name = "Build and test Osprey (Linux)"
            id = "RUNNER_1"
            path = "pwiz_tools/Osprey/tcbuild.sh"
        }
    }
    steps {
        update<ExecBuildStep>(0) {
            id = "RUNNER_1"
            clearConditions()
            arguments = "--i-agree-to-the-vendor-licenses --require-vendor-support"
            param("teamcity.kubernetes.executor.pull.policy", "")
        }
    }
}
